// Generated static result cards. No device or runtime data is embedded.
package eu.kanade.tachiyomi.extension.en.sandboxdiagnostics

import okio.ByteString.Companion.decodeBase64

internal object ReportImages {
    fun bytes(outcome: Outcome): ByteArray = when (outcome) {
        Outcome.NOT_RUN -> "".decodeBase64()!!.toByteArray()
        Outcome.PASS -> "".decodeBase64()!!.toByteArray()
        Outcome.ALLOWED -> "".decodeBase64()!!.toByteArray()
        Outcome.BLOCKED -> "".decodeBase64()!!.toByteArray()
        Outcome.UNAVAILABLE -> "".decodeBase64()!!.toByteArray()
        Outcome.ERROR -> "".decodeBase64()!!.toByteArray()
    }
}
